#!/usr/bin/env python3
"""Build a local, hash-bound figure review of an existing raw projection only."""
import argparse
import json
from pathlib import Path
import sys

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from PIL import Image
import sam3d_milestone as M
import upgrade_bundles as U

CSS='''*{box-sizing:border-box}body{margin:0;background:#f5f6ef;color:#163e33;font:15px/1.55 system-ui,sans-serif}a{color:inherit}main,header{max-width:1260px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;border-bottom:1px solid #d8e1d7}.brand{font-weight:750;text-decoration:none}.eyebrow{font-size:11px;letter-spacing:.13em;font-weight:700}h1{font-size:clamp(36px,5vw,64px);line-height:1.05;letter-spacing:-.045em;max-width:900px;margin:18px 0}p{max-width:850px;color:#52685e}.lead{font-size:19px}.badge{display:inline-block;padding:6px 11px;background:#dcebe1;border-radius:30px;font-size:12px;margin:4px 6px 4px 0}.scope{background:#e9eee4;padding:18px 22px;border-left:3px solid #739785;font-size:13px;max-width:none}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:30px 0 16px}button,.action{border:1px solid #abc1b4;border-radius:5px;padding:10px 15px;background:transparent;color:#163e33;font:600 13px system-ui;cursor:pointer;text-decoration:none}button[aria-pressed=true]{background:#163e33;color:#f5f6ef;border-color:#163e33}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{background:white;border:1px solid #d6dfd5;border-radius:9px;overflow:hidden}.card h2{font-size:15px;padding:18px;margin:0}.image-wrap{background:#e9eae4;min-height:290px;display:grid;place-items:center;padding:16px}.image-wrap img{display:block;width:100%;height:310px;object-fit:contain}.full .image-wrap img{height:auto;max-height:620px}.card p{font-size:12px;margin:0;padding:18px;min-height:90px}.facts{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:28px}.fact{border:1px solid #d6dfd5;border-radius:8px;padding:22px}.fact strong{font-size:38px;letter-spacing:-.04em;display:block}.fact p{font-size:13px;margin:5px 0}.fact h2{font-size:15px;margin:0}details{border-top:1px solid #d8e1d7;padding:20px 0;margin-top:25px}summary{cursor:pointer;font-weight:650}pre{overflow:auto;background:#edf1e8;padding:15px;font-size:12px}footer{border-top:1px solid #d8e1d7;padding:24px 0;margin-top:30px;color:#64776e;font-size:12px}#status{font-size:12px}#content[hidden]{display:none}@media(max-width:760px){main,header{padding:20px}.grid{grid-template-columns:1fr}.facts{grid-template-columns:1fr}.image-wrap img{height:300px}h1{font-size:42px}.lead{font-size:17px}}'''
JS='''(async()=>{'use strict';const get=id=>document.getElementById(id),assert=(v,m)=>{if(!v)throw Error(m)},SHA=/^[a-f0-9]{64}$/;let urls=[];const hash=async raw=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw)),x=>x.toString(16).padStart(2,'0')).join('');async function read(name,ref){assert(/^[a-z0-9-]+\\.(png|json)$/.test(name),'Unsafe figure path');const r=await fetch(name,{cache:'no-store',credentials:'omit'});assert(r.ok,'Figure file unavailable');const raw=await r.arrayBuffer();assert(raw.byteLength===ref.bytes&&raw.byteLength<=8*1024*1024&&await hash(raw)===ref.sha256,'Figure bytes changed');return raw;}try{const pinned=document.body.dataset.manifestSha;assert(SHA.test(pinned),'Figure manifest pin missing');const response=await fetch('manifest.json',{cache:'no-store',credentials:'omit'}),raw=await response.arrayBuffer();assert(raw.byteLength<1024*1024&&await hash(raw)===pinned,'Figure manifest changed');const d=JSON.parse(new TextDecoder().decode(raw));assert(d.format==='sam3d-raw-projection-review'&&d.version===1&&d.scope.optimized===false&&d.scope.accepted_source_video_pose===false&&d.scope.physical_accuracy_verified===false&&d.scope.simulation_ready===false,'Unsupported figure claims');const assets=new Map();for(const f of d.images){assert(SHA.test(f.sha256),'Unbound image');const bytes=await read(f.path,f),url=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));urls.push(url);assets.set(f.path,url);}let detail=true;function images(){get('cards').classList.toggle('full',!detail);for(const [id,name]of[['source','source-rgb'],['overlay','source-overlay'],['silhouette','silhouette-comparison']])get(id).src=assets.get(name+(detail?'-detail':'')+'.png');get('detail').setAttribute('aria-pressed',String(detail));get('full').setAttribute('aria-pressed',String(!detail));}get('detail').onclick=()=>{detail=true;images()};get('full').onclick=()=>{detail=false;images()};get('source-time').textContent='Source sample '+d.source.sample_index+' · '+d.source.timestamp_s.toFixed(6)+' s';get('iou').textContent=d.silhouette.IoU.toFixed(3);get('pointmap-error').textContent=d.camera.heldout_grid.median_px.toFixed(3)+' px';get('pointmap-scope').textContent=d.camera.heldout_grid.support.toLocaleString()+' offset-grid points from the SAME inferred pointmap. This measures pinhole consistency, not physical calibration.';get('camera-json').textContent=JSON.stringify({estimated_K:d.camera.K_estimated,training_grid:d.camera.training_grid,heldout_grid:d.camera.heldout_grid,pixel_mapping:d.camera.pixel_mapping},null,2);get('diagnostic').href=d.diagnostic.path;get('download').onclick=async()=>{const b=get('download');b.disabled=true;try{const n=d.native_glb;assert(/^\\/files\\/data\\/[a-zA-Z0-9_./-]+\\.glb$/.test(n.url)&&!n.url.split('/').some(x=>x.startsWith('.'))&&SHA.test(n.sha256),'Unbound native model');const r=await fetch(n.url,{cache:'force-cache',credentials:'omit'}),raw=await r.arrayBuffer();assert(r.ok&&raw.byteLength===n.bytes&&raw.byteLength<=16*1024*1024&&await hash(raw)===n.sha256,'Native model bytes changed');const u=URL.createObjectURL(new Blob([raw],{type:'model/gltf-binary'}));urls.push(u);const a=document.createElement('a');a.href=u;a.download='unchanged-native-earbud.glb';a.click();b.textContent='Verified native GLB downloaded';}catch(e){get('status').textContent=e.message}finally{b.disabled=false}};images();get('content').hidden=false;get('status').textContent='Verified source and derived image hashes · no inference runs on this page.';window.addEventListener('pagehide',()=>urls.forEach(URL.revokeObjectURL));}catch(e){get('status').textContent='Figure unavailable: '+e.message;get('content').hidden=true;}})();'''
HTML='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interaction Twin · Raw source projection</title><link rel="stylesheet" href="style.css"></head><body data-manifest-sha="%%SHA%%"><header><a class="brand" href="/showcase/index.html">◈ Interaction Twin</a><a href="/showcase/library.html">Explore the library ↗</a></header><main><div class="eyebrow">A REAL SAM 3D RESULT / SOURCE PROJECTION</div><h1>A 3D part, placed back into its source view.</h1><p class="lead">The unchanged generated earbud, its raw model layout and a camera estimated from the model's pointmap. Zero silhouette fitting.</p><div><span class="badge">Genuine saved model output</span><span class="badge">One source frame</span><span class="badge">Raw initializer · unvalidated pose</span></div><p class="scope">This is a projection diagnostic. The camera is an estimated prior from one inferred pointmap; scale, physical accuracy, video motion, insertion and contact remain unverified.</p><p id="status" role="status">Verifying saved source and derived images…</p><div id="content" hidden><div class="toolbar"><button id="detail" aria-pressed="true">Enlarged detail</button><button id="full" aria-pressed="false">Full source frame</button><span id="source-time" class="eyebrow"></span></div><div id="cards" class="grid"><article class="card"><h2>01 / Original video frame</h2><div class="image-wrap"><img id="source" alt="Original source view of the earbud"></div><p>Source pixels from the frame used for reconstruction. The detail view is a display crop with padding.</p></article><article class="card"><h2>02 / Raw 3D projection</h2><div class="image-wrap"><img id="overlay" alt="Unmodified generated mesh projected over the source using raw layout and estimated camera"></div><p>Generated vertex colours blended over the source. No manual pose, silhouette optimization or old model pose was used.</p></article><article class="card"><h2>03 / Visible silhouette comparison</h2><div class="image-wrap"><img id="silhouette" alt="SAM visible mask in amber, raw projected model in teal and overlapping pixels in white"></div><p>Amber: SAM visible mask. Teal: projected model. White: overlap. The SAM mask did not clip the render or determine the camera.</p></article></div><div class="facts"><section class="fact"><h2>Same-frame silhouette overlap</h2><strong id="iou"></strong><p>Intersection over union of the visible SAM mask and full projected mesh. A descriptive single-frame comparison, not a physical accuracy score.</p></section><section class="fact"><h2>Held-out inferred-pointmap residual</h2><strong id="pointmap-error"></strong><p id="pointmap-scope"></p></section></div><details><summary>How the camera and starting pose were obtained</summary><p>A fixed grid fits fx, fy, cx and cy from model-inferred 3D points and their native image coordinates. An offset grid reports residuals on disjoint pixels of that same pointmap. The model's saved layout is converted using the audited coordinate convention and rendered once. No optimizer, tracking, calibration target or pose search runs here.</p><pre id="camera-json"></pre></details><div class="toolbar"><button id="download">Download unchanged native GLB ↓</button><a id="diagnostic" class="action" download>Read full diagnostic JSON ↓</a><a href="/showcase/index.html" class="action">Return to the project ↗</a></div><footer>Local inspection · no API calls · no model selection · no accepted source pose · no robot simulation. The full source frame and raw render remain available separately from the enlarged display crop.</footer></div></main><script src="review.js"></script></body></html>'''


def build(diagnostic_directory,output):
    directory=M._directory(diagnostic_directory,ROOT);output=M._directory(output,ROOT,exists=False)
    if output.exists() or output.is_relative_to(directory):raise ValueError('Choose a fresh, separate review directory')
    diagnostic=U.read(directory/'diagnostic.json');plan=U.read(directory/'plan.json')
    if (diagnostic.get('fixture') not in (None,False) or plan.get('fixture') not in (None,False)
            or diagnostic.get('format')!='sam3d-fixed-raw-source-projection-diagnostic' or diagnostic.get('status')!='one_raw_projection_rendered'):
        raise ValueError('An existing completed raw projection is required')
    for k in ['optimized','native_glb_changed','source_video_pose_accepted','physical_accuracy_verified','simulation_ready']:
        if diagnostic.get(k) is not False:raise ValueError('Raw diagnostic scope differs')
    refs={f['path']:f for f in diagnostic['files']}
    if set(p.name for p in directory.iterdir())!=set(refs)|{'diagnostic.json'}:raise ValueError('Diagnostic file inventory changed')
    for name,r in refs.items():
        p=U._local(directory/name,ROOT)
        if p.stat().st_size!=r['bytes'] or U.sha(p)!=r['sha256']:raise ValueError('Diagnostic bytes changed')
    if U.sha(directory/'plan.json')!=diagnostic['plan_sha256']:raise ValueError('Fixed plan changed')
    crop=diagnostic['display_crop_xyxy'];payloads={};images=[]
    for name in ['source-rgb','source-overlay','silhouette-comparison']:
        source=directory/(name+'.png');payloads[source.name]=source.read_bytes()
        image=Image.open(source);detail=image.crop(crop)
        import io
        buffer=io.BytesIO();detail.save(buffer,format='PNG');payloads[name+'-detail.png']=buffer.getvalue()
    for name,raw in payloads.items():images.append({'path':name,'sha256':U.digest(raw),'bytes':len(raw)})
    payloads['diagnostic.json']=(directory/'diagnostic.json').read_bytes()
    glb=U._local(plan['native_glb']['path'],ROOT)
    if U.sha(glb)!=plan['native_glb']['sha256']:raise ValueError('Native model changed')
    manifest={'format':'sam3d-raw-projection-review','version':1,'images':images,
              'source':plan['source_binding']['source'],'camera':diagnostic['camera'],
              'silhouette':diagnostic['same_frame_silhouette_diagnostic'],
              'scope':{'optimized':False,'accepted_source_video_pose':False,'physical_accuracy_verified':False,'simulation_ready':False},
              'native_glb':{'url':'/files/'+plan['native_glb']['path'],'sha256':U.sha(glb),'bytes':glb.stat().st_size},
              'diagnostic':{'path':'diagnostic.json','sha256':U.digest(payloads['diagnostic.json']),'bytes':len(payloads['diagnostic.json'])},
              'display_crop_xyxy':crop,'full_source_and_derived_images_preserved':True,'new_models_or_api_calls':0}
    payloads['manifest.json']=U.encoded(manifest);payloads['style.css']=CSS.encode();payloads['review.js']=JS.encode()
    payloads['index.html']=HTML.replace('%%SHA%%',U.digest(payloads['manifest.json'])).encode()
    output.mkdir(parents=True,exist_ok=False)
    for name,raw in payloads.items():(output/name).write_bytes(raw)
    U.write(output/'build.json',{'format':'sam3d-raw-projection-review-build','version':1,'files':M._records(payloads),
             'builder_sha256':U.sha(Path(__file__)),'source_diagnostic_sha256':U.sha(directory/'diagnostic.json'),
             'new_models_or_api_calls':0,'native_glb_changed':False,'catalog_changed':False,'physical_accuracy_verified':False})
    return {'status':'raw_projection_review_built','review':output.relative_to(ROOT).as_posix()+'/index.html'}


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--diagnostic-directory',type=Path,required=True);parser.add_argument('--output',type=Path,required=True)
    args=parser.parse_args();print(json.dumps(build(args.diagnostic_directory,args.output),indent=2))
